CREATE TABLE compromisso (id_compromisso RAW(16) PRIMARY KEY, solicitacao_id RAW(16) NOT NULL UNIQUE, reserva_id RAW(16) NOT NULL, status VARCHAR2(30) NOT NULL CHECK(status IN ('EM_ANALISE','ACEITO','RECUSADO','CANCELADO')), criado_em TIMESTAMP WITH TIME ZONE NOT NULL, atualizado_em TIMESTAMP WITH TIME ZONE NOT NULL, cancelado_em TIMESTAMP WITH TIME ZONE, versao NUMBER(19));
CREATE TABLE cancelamento_antecipado (id RAW(16) PRIMARY KEY, solicitacao_id RAW(16) NOT NULL UNIQUE, correlation_id RAW(16) NOT NULL, criado_em TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE mensagem_processada (id_mensagem_processada RAW(16) PRIMARY KEY, message_id RAW(16) NOT NULL UNIQUE, correlation_id RAW(16), solicitacao_id RAW(16), tipo_mensagem VARCHAR2(255), processada_em TIMESTAMP WITH TIME ZONE);
CREATE TABLE outbox_event (id RAW(16) PRIMARY KEY, message_id RAW(16) NOT NULL UNIQUE, correlation_id RAW(16) NOT NULL, tipo_evento VARCHAR2(255) NOT NULL, payload CLOB NOT NULL, status VARCHAR2(30) NOT NULL CHECK(status IN ('PENDENTE','PROCESSANDO','PUBLICADO')), criado_em TIMESTAMP WITH TIME ZONE NOT NULL, publicado_em TIMESTAMP WITH TIME ZONE, reservado_ate TIMESTAMP WITH TIME ZONE, token_reserva RAW(16));
CREATE TABLE solicitacao_lock (solicitacao_id RAW(16) PRIMARY KEY);
CREATE TABLE solicitacao_atendimento (id_solicitacao_atendimento RAW(16) PRIMARY KEY, id_solicitacao RAW(16), resultado_atendimento NUMBER(5), recebido_em TIMESTAMP WITH TIME ZONE, processado_em TIMESTAMP WITH TIME ZONE);
